import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import path from 'path';
// We import the static TypeScript interfaces generated by our build script
import type { ProtoGrpcType } from '@nexus/proto/dist/search';

// Path to the original .proto file so the C++ engine can read the binary tags at runtime
const PROTO_PATH = path.resolve(__dirname, '../../../packages/proto/src/search.proto');

// Load the .proto file into memory
const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  keepCase: true,
  longs: String,
  enums: String,
  defaults: true,
  oneofs: true,
});

// Convert it to a usable gRPC object with strict typings
const protoDescriptor = grpc.loadPackageDefinition(packageDefinition) as unknown as ProtoGrpcType;

// Instantiate the Search Client pointing to the internal microservice
export const searchClient = new protoDescriptor.search.SearchService(
  'localhost:50051', // We will build this service on port 50051 later
  grpc.credentials.createInsecure() // Internal network, no TLS needed
);
